  private __actions__?: Dispatcher<Actions<Mod>>
  /** @internal */
  constructor(
    private pos: ContextPosition,
    private store: Store<any>,
    private mutationsClass: Class<unknown> | undefined,
    private actionsClass: Class<unknown> | undefined
